            else:
                return [dx_try, dy_try]

    # Fallback heuristic based on simple fields
    # If there are enemies or resources reported, try to drift away from or toward as reasonable
    if observation.get("task") in ("resource_collection", "territory_control", "pursuit_evasion"):
        # avoid obvious walls if any field exists
